export type PicrossHints = {
  rows: number[][];
  columns: number[][];
};

// -1 = unknown, 0 = empty, 1 = filled
export type SolverCell = -1 | 0 | 1;
export type SolverGrid = SolverCell[][];

export type PicrossSolveResult = {
  // Number of solutions found, capped at 2 ("2" means "2 or more")
  solutionCount: 0 | 1 | 2;
  // True when line logic alone fully solves the puzzle (no guessing needed)
  logicSolvable: boolean;
  // First solution found (true = filled), if any
  solution: boolean[][] | null;
  // Cells still undetermined after line logic
  unknownCount: number;
  // True when the search hit its deadline, so the counts above are inconclusive
  timedOut?: boolean;
};

/**
 * Solves a single line. Finds every cell that has the same value in all
 * arrangements of the clues consistent with the known cells.
 * Returns null if no arrangement fits.
 */
export function solveLine(
  line: SolverCell[],
  clues: number[],
): SolverCell[] | null {
  return analyzeLine(line, clues)?.cells ?? null;
}

function analyzeLine(
  line: SolverCell[],
  clues: number[],
): { cells: SolverCell[]; placements: number } | null {
  const n = line.length;
  const blocks = clues.filter((clue) => clue > 0);
  const m = blocks.length;

  const emptyPrefix = new Array<number>(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    emptyPrefix[i + 1] = emptyPrefix[i]! + (line[i] === 0 ? 1 : 0);
  }

  const fits = (pos: number, k: number) => {
    const length = blocks[k]!;
    if (pos + length > n) return false;
    if (emptyPrefix[pos + length] !== emptyPrefix[pos]) return false;
    return pos + length === n || line[pos + length] !== 1;
  };
  // Position after placing block k at pos, including the mandatory gap
  const after = (pos: number, k: number) => Math.min(pos + blocks[k]! + 1, n);

  // suffix[pos][k]: number of valid arrangements of blocks k.. in cells pos..
  const suffix = Array.from({ length: n + 1 }, () =>
    new Array<number>(m + 1).fill(0),
  );
  suffix[n]![m] = 1;
  for (let pos = n - 1; pos >= 0; pos--) {
    for (let k = 0; k <= m; k++) {
      let count = line[pos] !== 1 ? suffix[pos + 1]![k]! : 0;
      if (k < m && fits(pos, k)) count += suffix[after(pos, k)]![k + 1]!;
      suffix[pos]![k] = count;
    }
  }
  if (!suffix[0]![0]) return null;

  const reach = Array.from({ length: n + 1 }, () =>
    new Array<boolean>(m + 1).fill(false),
  );
  const canEmpty = new Array<boolean>(n).fill(false);
  const filledDiff = new Array<number>(n + 1).fill(0);
  reach[0]![0] = true;

  for (let pos = 0; pos < n; pos++) {
    for (let k = 0; k <= m; k++) {
      if (!reach[pos]![k]) continue;

      if (line[pos] !== 1 && suffix[pos + 1]![k]) {
        canEmpty[pos] = true;
        reach[pos + 1]![k] = true;
      }

      if (k < m && fits(pos, k)) {
        const next = after(pos, k);
        if (!suffix[next]![k + 1]) continue;
        filledDiff[pos]!++;
        filledDiff[pos + blocks[k]!]!--;
        if (pos + blocks[k]! < n) canEmpty[pos + blocks[k]!] = true;
        reach[next]![k + 1] = true;
      }
    }
  }

  const result: SolverCell[] = [];
  let filledCount = 0;
  for (let i = 0; i < n; i++) {
    filledCount += filledDiff[i]!;
    const canFill = filledCount > 0;
    if (canFill && !canEmpty[i]) result.push(1);
    else if (!canFill && canEmpty[i]) result.push(0);
    else if (!canFill && !canEmpty[i]) return null;
    else result.push(-1);
  }
  return { cells: result, placements: suffix[0]![0]! };
}

// Re-solves only lines affected by changed cells. False on contradiction.
function propagate(
  grid: SolverGrid,
  hints: PicrossHints,
  lineCounts: number[],
  changedCell?: { x: number; y: number },
): boolean {
  const height = grid.length;
  const width = grid[0]?.length ?? 0;
  const queue: number[] = [];
  const queued = new Array<boolean>(height + width).fill(false);
  const enqueue = (line: number) => {
    if (!queued[line]) {
      queued[line] = true;
      queue.push(line);
    }
  };

  if (changedCell) {
    enqueue(changedCell.y);
    enqueue(height + changedCell.x);
  } else {
    for (let line = 0; line < height + width; line++) enqueue(line);
  }

  for (let next = 0; next < queue.length; next++) {
    const line = queue[next]!;
    queued[line] = false;
    if (line < height) {
      const y = line;
      const solved = analyzeLine(grid[y]!, hints.rows[y] ?? []);
      if (!solved) return false;
      lineCounts[line] = solved.placements;
      for (let x = 0; x < width; x++) {
        if (solved.cells[x] !== grid[y]![x]) {
          grid[y]![x] = solved.cells[x]!;
          enqueue(height + x);
        }
      }
    } else {
      const x = line - height;
      const column = grid.map((row) => row[x]!);
      const solved = analyzeLine(column, hints.columns[x] ?? []);
      if (!solved) return false;
      lineCounts[line] = solved.placements;
      for (let y = 0; y < height; y++) {
        if (solved.cells[y] !== grid[y]![x]) {
          grid[y]![x] = solved.cells[y]!;
          enqueue(y);
        }
      }
    }
  }
  return true;
}

function findUnknown(grid: SolverGrid) {
  for (let y = 0; y < grid.length; y++) {
    const x = grid[y]!.indexOf(-1);
    if (x !== -1) return { x, y };
  }
  return null;
}

function findGuess(grid: SolverGrid, lineCounts: number[]) {
  const width = grid[0]?.length ?? 0;
  let best: { x: number; y: number } | null = null;
  let bestScore = Infinity;
  for (let y = 0; y < grid.length; y++) {
    for (let x = 0; x < width; x++) {
      if (grid[y]![x] !== -1) continue;
      const score = lineCounts[y]! * lineCounts[grid.length + x]!;
      if (best === null || score < bestScore) {
        best = { x, y };
        bestScore = score;
      }
    }
  }
  return best;
}

function hasAlternativeRectangle(
  grid: SolverGrid,
  hints: PicrossHints,
  initial: SolverGrid | undefined,
  deadline: number,
): boolean {
  const height = grid.length;
  const width = grid[0]?.length ?? 0;
  const matches = (line: SolverCell[], a: number, b: number, clues: number[]) => {
    let clueIndex = 0;
    let run = 0;
    for (let i = 0; i < line.length; i++) {
      const filled = i === a || i === b ? line[i] === 0 : line[i] === 1;
      if (filled) {
        run++;
      } else if (run > 0) {
        if (clues[clueIndex++] !== run) return false;
        run = 0;
      }
    }
    if (run > 0 && clues[clueIndex++] !== run) return false;
    return clueIndex === clues.length;
  };
  const columns = Array.from({ length: width }, (_, x) =>
    grid.map((row) => row[x]!),
  );
  const rowClues = grid.map((_, y) => (hints.rows[y] ?? []).filter((n) => n > 0));
  const columnClues = columns.map((_, x) =>
    (hints.columns[x] ?? []).filter((n) => n > 0),
  );

  for (let y1 = 0; y1 < height; y1++) {
    for (let y2 = y1 + 1; y2 < height; y2++) {
      if (Date.now() >= deadline) return false;
      for (let x1 = 0; x1 < width; x1++) {
        for (let x2 = x1 + 1; x2 < width; x2++) {
          if (
            grid[y1]![x1] === grid[y1]![x2] ||
            grid[y1]![x1] === grid[y2]![x1] ||
            grid[y1]![x1] !== grid[y2]![x2] ||
            (initial &&
              (initial[y1]?.[x1] !== -1 ||
                initial[y1]?.[x2] !== -1 ||
                initial[y2]?.[x1] !== -1 ||
                initial[y2]?.[x2] !== -1))
          ) {
            continue;
          }
          if (
            matches(grid[y1]!, x1, x2, rowClues[y1]!) &&
            matches(grid[y2]!, x1, x2, rowClues[y2]!) &&
            matches(columns[x1]!, y1, y2, columnClues[x1]!) &&
            matches(columns[x2]!, y1, y2, columnClues[x2]!)
          ) {
            return true;
          }
        }
      }
    }
  }
  return false;
}

/**
 * Solves a puzzle from its hints using line logic, falling back to
 * backtracking to determine whether the solution is unique.
 */
export function solvePicross(
  hints: PicrossHints,
  size: { width: number; height: number },
  initial?: SolverGrid,
  options: { logicOnly?: boolean; deadline?: number } = {},
): PicrossSolveResult {
  const start: SolverGrid =
    initial?.map((row) => [...row]) ??
    Array.from({ length: size.height }, () =>
      new Array<SolverCell>(size.width).fill(-1),
    );

  const lineCounts = new Array<number>(size.height + size.width).fill(0);
  if (!propagate(start, hints, lineCounts)) {
    return {
      solutionCount: 0,
      logicSolvable: false,
      solution: null,
      unknownCount: size.width * size.height,
    };
  }
  const logicSolvable = findUnknown(start) === null;
  const unknownCount = start.reduce(
    (total, row) => total + row.filter((cell) => cell === -1).length,
    0,
  );

  let count = 0;
  let solution: boolean[][] | null = null;
  let timedOut = false;

  if (options.logicOnly && !logicSolvable) {
    return { solutionCount: 0, logicSolvable, solution: null, unknownCount };
  }

  const search = (grid: SolverGrid, counts: number[]) => {
    if (options.deadline !== undefined && Date.now() > options.deadline) {
      timedOut = true;
    }
    if (timedOut) return;
    const cell = findGuess(grid, counts);
    if (!cell) {
      count++;
      solution ??= grid.map((row) => row.map((value) => value === 1));
      if (
        count === 1 &&
        !logicSolvable &&
        hasAlternativeRectangle(
          grid,
          hints,
          initial,
          Math.min(options.deadline ?? Infinity, Date.now() + 20),
        )
      ) {
        count = 2;
      }
      return;
    }
    for (const value of [1, 0] as const) {
      if (count >= 2 || timedOut) return;
      const copy = grid.map((row) => [...row]);
      const nextCounts = [...counts];
      copy[cell.y]![cell.x] = value;
      if (propagate(copy, hints, nextCounts, cell)) search(copy, nextCounts);
    }
  };
  search(start, lineCounts);

  return {
    // An interrupted search can't vouch for uniqueness
    solutionCount: timedOut ? 0 : (Math.min(count, 2) as 0 | 1 | 2),
    logicSolvable,
    solution: timedOut ? null : solution,
    unknownCount,
    timedOut,
  };
}

/**
 * Generates a random solution whose hints can be solved by line logic alone.
 * Stops after a time budget so large grids can't freeze the page; in that case
 * the candidate needing the least guessing is returned.
 */
export function generateSolvableSolution(
  size: { width: number; height: number },
  getHints: (solution: boolean[][]) => PicrossHints,
  maxAttempts = 300,
  timeBudgetMs = 750,
  random: () => number = Math.random,
  requireLogicSolvable = false,
): boolean[][] {
  const deadline = Date.now() + timeBudgetMs;
  let best: boolean[][] | null = null;
  let bestUnknown = Infinity;

  const finish = (solution: boolean[][]) => {
    // Re-solve with a short cap so the log never stalls large grids
    const result = solvePicross(getHints(solution), size, undefined, {
      deadline: Date.now() + 250,
    });
    console.log(
      `[picross] generated ${size.width}x${size.height}: logicSolvable=${result.logicSolvable}, solutionCount=${
        result.solutionCount === 0 && !result.logicSolvable
          ? "unknown (search timed out)"
          : result.solutionCount === 2
            ? "2+"
            : result.solutionCount
      }, unknownCells=${result.unknownCount}`,
    );
    return solution;
  };

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const density = 0.45 + random() * 0.15;
    const candidate = Array.from({ length: size.height }, () =>
      Array.from({ length: size.width }, () => random() < density),
    );
    const result = solvePicross(getHints(candidate), size, undefined, {
      logicOnly: true,
    });
    if (result.logicSolvable) return finish(candidate);
    if (result.unknownCount < bestUnknown) {
      best = candidate;
      bestUnknown = result.unknownCount;
    }
    if (Date.now() > deadline) break;
  }
  if (requireLogicSolvable || !best) {
    throw new Error("Could not generate a logic-solvable puzzle");
  }
  return finish(best);
}
